local T = import("test/environment.lua")
local deflate = import("goluwa/codecs/deflate.lua")

T.Test("deflate code length repeat across the literal and distance tables", function()
	local raw = "\x0d\xc1\xa1\x00\x00\x00\x00\x00\x20\xd6\xfc\x25\x1a\x02"
	T(deflate.Decode(raw, "raw"):ReadBytes(1))["=="]("a")
end)

local function from_hex(hex)
	return (hex:gsub("%x%x", function(byte)
		return string.char(tonumber(byte, 16))
	end))
end

local expected = from_hex(
	""
)
local vectors = {
	{
		format = "raw",
		compressed = "",
	},
	{
		format = "zlib",
		compressed = "",
	},
	{
		format = "gzip",
		compressed = "",
	},
}

T.Test("deflate decodes raw, zlib and gzip containers", function()
	for _, vector in ipairs(vectors) do
		local compressed = from_hex(vector.compressed)
		local out, size = deflate.Decode(compressed, vector.format)
		T(size)["=="](#expected)
		T(require("ffi").string(out.Buffer, size) == expected)["=="](true)
		out, size = deflate.Decode(compressed)
		T(require("ffi").string(out.Buffer, size) == expected)["=="](true)
	end
end)

T.Test("deflate worker result equals the inline result", function()
	local ffi = require("ffi")

	for _, vector in ipairs(vectors) do
		local meta, blob = deflate.DecodeJob(from_hex(vector.compressed), vector.format):Await()
		T(meta.size)["=="](#expected)
		T(ffi.string(blob.ptr, blob.len) == expected)["=="](true)
	end
end)
